      kind: 'taxon',
      reason: `scoped to ${s.taxa.join(', ')} (${s.basis}); the design is ${taxon}${p.placed && p.ancestors.length ? `, which the NCBI taxonomy places inside ${p.ancestors.slice(0, 4).join(', ')}` : ''}.`,
      scope: s,
